{"content":"package config

import (
	"strings"
	"testing"
	"time"
)

func env(m map[string]string) func(string) string { return func(k string) string { return m[k] } }

func TestLoadDefaults(t *testing.T) {
	c, err := Load(env(nil))
	if err != nil || c.Host != "localhost" || c.Port != 8080 || c.Workers != 4 {
		t.Fatalf("%+v %v", c, err)
	}
	if c.Timeout != 30*time.Second {
		t.Fatalf("Timeout = %v, want 30s", c.Timeout)
	}
	if c.Tags != nil {
		t.Fatalf("Tags = %#v, want nil", c.Tags)
	}
}

func TestLoadOverrides(t *testing.T) {
	c, err := Load(env(map[string]string{"APP_PORT": "9000", "APP_DEBUG": "true"}))
	if err != nil || c.Port != 9000 || !c.Debug {
		t.Fatalf("%+v %v", c, err)
	}
}

func TestLoadTimeoutAndTags(t *testing.T) {
	c, err := Load(env(map[string]string{
		"APP_TIMEOUT": "1m5s",
		"APP_TAGS": " a , b ,,c ",
	}))
	if err != nil {
		t.Fatal(err)
	}
	if c.Timeout != time.Minute+5*time.Second {
		t.Fatalf("Timeout = %v", c.Timeout)
	}
	want := []string{"a", "b", "c"}
	if len(c.Tags) != len(want) {
		t.Fatalf("Tags = %#v, want %#v", c.Tags, want)
	}
	for i := range want {
		if c.Tags[i] != want[i] {
			t.Fatalf("Tags = %#v, want %#v", c.Tags, want)
		}
	}
}

func TestLoadCollectsAllErrors(t *testing.T) {
	c, err := Load(env(map[string]string{
		"APP_PORT":    "abc",
		"APP_DEBUG":   "notabool",
		"APP_WORKERS": "-2",
		"APP_TIMEOUT": "soon",
	}))
	if err == nil {
		t.Fatal("expected error")
	}
	for _, name := range []string{"APP_PORT", "APP_DEBUG", "APP_WORKERS", "APP_TIMEOUT"} {
		if !strings.Contains(err.Error(), name) {
			t.Errorf("error %q does not mention %s", err, name)
		}
	}
	if c != (Config{}) {
		t.Fatalf("config on error = %+v, want zero", c)
	}
}

func TestMerge(t *testing.T) {
	base := Config{Host: "localhost", Port: 8080, Workers: 4, Timeout: 30 * time.Second, Tags: []string{"x", "y"}}
	override := Config{Port: 9090, Debug: true, Timeout: time.Hour, Tags: []string{}}
	m := Merge(base, override)
	if m.Host != "localhost" || m.Port != 9090 || !m.Debug || m.Workers != 4 || m.Timeout != time.Hour {
		t.Fatalf("merged = %+v", m)
	}
	if m.Tags == nil || len(m.Tags) != 0 {
		t.Fatalf("Tags = %#v, want non-nil empty", m.Tags)
	}
	if base.Tags[0] != "x" || base.Tags[1] != "y" || len(base.Tags) != 2 {
		t.Fatalf("base Tags modified: %#v", base.Tags)
	}
	if override.Tags != nil && len(override.Tags) != 0 {
		t.Fatalf("override Tags modified: %#v", override.Tags)
	}
}

func TestMergeZeroOverrideKeepsBase(t *testing.T) {
	base := Config{Host: "h", Port: 1, Debug: true, Workers: 2, Timeout: 5 * time.Second, Tags: []string{"a"}}
	m := Merge(base, Config{})
	if m != base {
		t.Fatalf("merged = %+v, want base %+v", m, base)
	}
}

func TestMergeCopiesOverrideTags(t *testing.T) {
	base := Config{}
	override := Config{Tags: []string{"a", "b"}}
	m := Merge(base, override)
	override.Tags[0] = "changed"
	if m.Tags[0] != "a" {
		t.Fatalf("merged Tags share backing array with override: %#v", m.Tags)
	}
}
